"""Isolated generated byte/JSON boundaries; optional cached REAL FITS replay.

The generated bytes here are not FITS or observations and never enter product
assets. The integration test only uses the independently downloaded Phase 3 input.
"""
from __future__ import annotations

import json
import time
from dataclasses import replace
from types import SimpleNamespace

import pytest

from services import provenance as p

URL = "https://irsa.ipac.caltech.edu/ibe/data/spherex/dr1/level2/example.fits?center=10,20&size=0.2"


def record(tmp_path, *, content=b"isolated test-only hash boundary"):
    item = p.store_input(content, tmp_path / "store", source_url=URL,
                         cutout={"ra": 10.0, "dec": 20.0, "size_deg": 0.2})
    return p.make_record(kind="spectrum", query={"ra": 10.0, "dec": 20.0}, inputs=[item],
                         exposures=[{"input_sha256": item["sha256"], "epoch_id": "2025_E1", "detector": 1,
                                     "extraction": {"ra": 10.0, "dec": 20.0}, "expected_channel": None}],
                         method={"name": "test_boundary_only"}, code={}, environment={})


def test_timestamps_do_not_change_identity_but_science_does(tmp_path):
    first = record(tmp_path)
    second = record(tmp_path)
    second["created_at"] = "2040-01-01T00:00:00Z"
    second["retrieved_at"] = {key: "2040-01-01T00:00:00Z" for key in second["retrieved_at"]}
    assert first["analysis_id"] == second["analysis_id"]
    p.validate_record(second)
    second["identity"]["exposures"][0]["extraction"]["ra"] += 0.0001
    with pytest.raises(p.ProvenanceError, match="fingerprint"):
        p.validate_record(second)


@pytest.mark.parametrize("value", [float("nan"), float("inf"), float("-inf"), {1: "key"}, (1, 2)])
def test_canonical_json_rejects_ambiguous_types(value):
    with pytest.raises(p.ProvenanceError):
        p.canonical_json({"value": value})


@pytest.mark.parametrize("url", ["http://irsa.ipac.caltech.edu/ibe/data/spherex/dr1/a", "file:///etc/passwd",
                                   "https://localhost/a", "https://irsa.ipac.caltech.edu.evil.test/a",
                                   "https://user:password@irsa.ipac.caltech.edu/ibe/data/spherex/dr1/a",
                                   "https://irsa.ipac.caltech.edu/ibe/data/spherex/dr1/../../etc",
                                   "https://irsa.ipac.caltech.edu/ibe/data/spherex/dr1/%2e%2e/a",
                                   "https://irsa.ipac.caltech.edu/ibe/data/spherex/qr2/a"])
def test_url_rejection(url):
    with pytest.raises(p.ProvenanceError):
        p.validate_source_url(url)


def test_tampered_store_key_even_with_recomputed_id_is_rejected(tmp_path):
    item = record(tmp_path)
    item["identity"]["inputs"][0]["store_key"] = "../../secrets"
    item["analysis_id"] = p.fingerprint(item["identity"])
    with pytest.raises(p.ProvenanceError, match="content-addressed"):
        p.validate_record(item)


def test_corrupt_retained_input_not_replaced(tmp_path):
    item = record(tmp_path)
    path = next(iter(p.verify_inputs(item, tmp_path / "store").values()))
    path.write_bytes(b"wrong")
    with pytest.raises(p.ProvenanceError, match="mismatch"):
        p.verify_inputs(item, tmp_path / "store")
    with pytest.raises(p.ProvenanceError, match="mismatch"):
        p.acquire_inputs(item, tmp_path / "store")
    assert path.read_bytes() == b"wrong"


def test_changed_download_fails_without_publication(tmp_path, monkeypatch):
    item = record(tmp_path)
    import httpx
    original_client = httpx.Client
    transport = httpx.MockTransport(lambda request: httpx.Response(200, content=b"not pinned bytes"))
    monkeypatch.setattr(httpx, "Client", lambda **kwargs: original_client(transport=transport, **kwargs))
    with pytest.raises(p.ProvenanceError, match="mismatch"):
        p.acquire_inputs(item, tmp_path / "empty")
    assert not (tmp_path / "empty" / item["identity"]["inputs"][0]["store_key"]).exists()


def test_archive_redirect_fails(tmp_path, monkeypatch):
    item = record(tmp_path)
    import httpx
    original_client = httpx.Client
    transport = httpx.MockTransport(lambda request: httpx.Response(302, headers={"Location": "http://localhost/secret"}))
    monkeypatch.setattr(httpx, "Client", lambda **kwargs: original_client(transport=transport, **kwargs))
    with pytest.raises(p.ProvenanceError):
        p.acquire_inputs(item, tmp_path / "empty")


def test_duplicate_json_key_rejected(tmp_path):
    path = tmp_path / "record.json"
    path.write_text('{"schema_version":"a","schema_version":"b"}')
    with pytest.raises(p.ProvenanceError, match="Duplicate JSON"):
        p.read_record(path)


def test_channel_comparison_exact_states_and_tolerant_floats():
    channel = {"flux_ujy": 1.2, "flags": 2097152, "is_used_in_photometry": False}
    assert not p.verify_channels(channel, dict(channel, flux_ujy=1.2 + 1e-12, extra_diagnostic=42))
    assert p.verify_channels(channel, dict(channel, flags=2097153))
    assert p.verify_channels(channel, dict(channel, is_used_in_photometry=0))
    assert p.verify_channels(channel, dict(channel, flux_ujy=None))
    assert p.verify_channels(None, channel)


def test_code_identity_captures_untracked_source_not_secrets(tmp_path):
    source = tmp_path / "backend/services/new.py"
    source.parent.mkdir(parents=True)
    source.write_text("value = 1\n")
    (tmp_path / ".env").write_text("SECRET=must-not-appear")
    first = p.capture_code_identity(tmp_path)
    source.write_text("value = 2\n")
    second = p.capture_code_identity(tmp_path)
    assert first["source_digest"] != second["source_digest"]
    assert list(first["files"]) == ["backend/services/new.py"]
    assert "SECRET" not in json.dumps(first)


def test_record_round_trip(tmp_path):
    original = record(tmp_path)
    path = tmp_path / "analysis.json"
    p.write_record(path, original)
    assert p.read_record(path) == original


