def test_staging_offline_missing_input_never_calls_network(tmp_path, monkeypatch):
    from core.config import settings
    from scripts.stage_phase4 import PinnedArchive
    config = replace(settings, cache_dir=tmp_path / "cache")
    archive = PinnedArchive(target=SimpleNamespace(ra_epoch2025=10.0, dec_epoch2025=20.0),
                            uris=[URL.split("?")[0]], config=config,
                            deadline_at=time.monotonic() + 30, offline=True)
    def no_network(*args, **kwargs):
        pytest.fail("Offline staging attempted archive access")
    monkeypatch.setattr(archive.client, "fetch_cutouts", no_network)
    archive.prepare(0.2)
    assert archive.records == []
    assert archive.discovery_metadata["verified_exposure_count"] == 0
    assert archive.discovery_metadata["failed_inputs"][0]["reason"] == "EXACT_CUTOUT_NOT_RETAINED_OFFLINE"


def test_staging_reuse_requires_exact_cutout_and_verified_hash(tmp_path):
    from core.config import settings
    from scripts.stage_phase4 import PinnedArchive, ProductLocator
    old = tmp_path / "old-stage"
    locator = ProductLocator(URL.split("?")[0])
    content = b"isolated source-identity boundary, not a FITS observation"
    descriptor = p.store_input(content, old / "cache/analysis-inputs",
                               source_url=locator.cutout_url(10.0, 20.0, 0.2),
                               cutout={"ra": 10.0, "dec": 20.0, "size_deg": 0.2})
    (old / "stage-report.json").write_bytes(p.canonical_json({"targets": [
        {"discovery": {"cutout_requests": [descriptor]}}]}))
    archive = PinnedArchive(target=SimpleNamespace(ra_epoch2025=10.0, dec_epoch2025=20.0),
                            uris=[locator.uri], config=replace(settings, cache_dir=tmp_path / "new-cache"),
                            deadline_at=time.monotonic() + 30, offline=True, input_stages=[old])
    archive._seed_exact_cache(locator, 0.2)
    exact = archive.client._cutout_cache_path(locator, 10.0, 20.0, 0.2)
    assert exact.read_bytes() == content
    archive._seed_exact_cache(locator, 0.3)
    assert not archive.client._cutout_cache_path(locator, 10.0, 20.0, 0.3).exists()
    exact.unlink()
    (old / "cache/analysis-inputs" / descriptor["store_key"]).write_bytes(b"changed")
    with pytest.raises(p.ProvenanceError, match="hash mismatch"):
        archive._seed_exact_cache(locator, 0.2)


def test_staging_cannot_write_approved_golden_or_existing_output(tmp_path):
    from core.config import settings
    from scripts.stage_phase4 import stage
    with pytest.raises(p.ProvenanceError, match="outside"):
        stage(SimpleNamespace(output=settings.golden_cache_dir / "new-disallowed-stage"))
    with pytest.raises(FileExistsError):
        stage(SimpleNamespace(output=tmp_path))


def test_display_asset_links_survive_another_query_render(tmp_path):
    """Two different real saved frames stand in for successive render outputs."""
    from services.recording import freeze_product_assets, product_assets
    real_frames = sorted((p.REPO_ROOT / "golden_cache/wise_0855").glob("*D6.webp"))
    assert len(real_frames) >= 2
    first_bytes, second_bytes = [path.read_bytes() for path in real_frames[:2]]
    assert first_bytes != second_bytes
    mutable = tmp_path / "epoch_D6.webp"
    def product():
        return {"epochs": [{"frames": {"6": mutable.name}}], "differences": {}}
    mutable.write_bytes(first_bytes)
    first = product()
    freeze_product_assets(first, tmp_path)
    frozen_name = first["epochs"][0]["frames"]["6"]
    expected = product_assets(first, tmp_path)
    mutable.write_bytes(second_bytes)
    second = product()
    freeze_product_assets(second, tmp_path)
    assert second["epochs"][0]["frames"]["6"] != frozen_name
    assert (tmp_path / frozen_name).read_bytes() == first_bytes
    assert product_assets(first, tmp_path) == expected
    freeze_product_assets(first, tmp_path)
    assert first["epochs"][0]["frames"]["6"] == frozen_name
    telemetry = next((p.REPO_ROOT / "golden_cache/wise_0855").glob("telemetry_*.bin.gz"))
    (tmp_path / telemetry.name).write_bytes(telemetry.read_bytes())
    first["epochs"][0]["telemetry"] = {"url": telemetry.name}
    first["differences"] = {"pair": {"frames": {"6": mutable.name}}}
    freeze_product_assets(first, tmp_path)
    from services.telemetry import is_telemetry_filename
    assert is_telemetry_filename(first["epochs"][0]["telemetry"]["url"])
    assert first["differences"]["pair"]["frames"]["6"] == second["epochs"][0]["frames"]["6"]


@pytest.mark.parametrize("sample_index", [0, 10])
def test_real_cached_input_offline_replay(tmp_path, sample_index):
    report = p.REPO_ROOT / "docs/evidence/phase3/phase3-science-results.json"
    if not report.is_file():
        pytest.skip("Real Phase 3 source manifest unavailable")
    sample = json.loads(report.read_text())["samples"][sample_index]
    path = p.REPO_ROOT / sample["path"]
    if not path.is_file():
        pytest.skip("Real Phase 3 FITS input not locally retained; never generate a replacement")
    content = path.read_bytes()
    assert p.content_hash(content) == sample["sha256"]
    from scripts.stage_phase4 import record_from_fits
    artifact, metadata = record_from_fits(sample["uri"], content)
    assert artifact.band == sample["band"]
    assert metadata["time_scale"] == "utc"
    assert artifact.mjd_lower == sample["analysis"]["dates"]["MJD-BEG"]
    from services.spherex_pipeline import parse_cutout
    from services.spectrophotometry import extract_channel
    from scripts.replay_analysis import replay
    parsed = parse_cutout(content, sample["ra"], sample["dec"])
    expected = extract_channel(parsed, sample["band"])
    if sample_index == 10:
        assert expected is not None and expected["flux_ujy"] is None
    source = "https://irsa.ipac.caltech.edu/" + sample["uri"]
    source += f'?center={sample["ra"]:.6f},{sample["dec"]:.6f}&size={sample["fetch_size_deg"]:.6f}'
    item = p.store_input(content, tmp_path / "store", source_url=source,
                         cutout={"ra": sample["ra"], "dec": sample["dec"], "size_deg": sample["fetch_size_deg"]})
    analysis = p.make_record(kind="spectrum", query={"ra": sample["ra"], "dec": sample["dec"]}, inputs=[item],
                             exposures=[{"input_sha256": item["sha256"], "epoch_id": sample["epoch_id"],
                                         "detector": sample["band"], "extraction": {"ra": sample["ra"], "dec": sample["dec"]},
                                         "expected_channel": expected}], method=p.native_method())
    result = replay(analysis, tmp_path / "store", tmp_path / "output")
    assert result["verified"] is True
    assert result["scientific_validation"] == "not_established_by_replay"
    with pytest.raises(FileExistsError):
        replay(analysis, tmp_path / "store", tmp_path / "output")
